import json,sys,re
from remote import root,sql
c=sys.argv[1];reg=json.loads((root/(c+'-fixtures.json')).read_text());prefix=reg['prefix'];assert re.fullmatch('SNAPDETAIL1486-(31|32)',prefix)
q="SELECT JSON_OBJECT('id',s.id,'uuid',s.uuid,'name',s.name,'status',s.status,'removed',s.removed,'size',s.size,'type',s.snapshot_type,'description',s.type_description,'volume',v.uuid,'volumeName',v.name,'volumeState',v.state,'volumeRemoved',v.removed,'account',a.account_name,'domain',d.uuid,'vm',vm.uuid,'vmName',vm.display_name,'vmState',vm.state) FROM snapshots s JOIN volumes v ON v.id=s.volume_id JOIN account a ON a.id=s.account_id JOIN domain d ON d.id=s.domain_id LEFT JOIN vm_instance vm ON vm.id=v.instance_id WHERE s.name LIKE '"+prefix+"%'; SELECT JSON_OBJECT('id',r.id,'snapshot',s.uuid,'role',r.store_role,'store',COALESCE(i.uuid,p.uuid),'storeName',COALESCE(i.name,p.name),'size',r.size,'physical',r.physical_size,'state',r.state,'parentId',r.parent_snapshot_id,'parent',parent.uuid,'path',r.install_path) FROM snapshot_store_ref r JOIN snapshots s ON s.id=r.snapshot_id LEFT JOIN image_store i ON r.store_role='Image' AND i.id=r.store_id LEFT JOIN storage_pool p ON r.store_role='Primary' AND p.id=r.store_id LEFT JOIN snapshots parent ON parent.id=r.parent_snapshot_id WHERE s.name LIKE '"+prefix+"%'; SELECT JSON_OBJECT('uuid',v.uuid,'id',v.id,'name',v.name,'state',v.state,'size',v.size,'removed',v.removed,'path',v.path,'pool',p.uuid,'vm',vm.uuid) FROM volumes v LEFT JOIN storage_pool p ON p.id=v.pool_id LEFT JOIN vm_instance vm ON vm.id=v.instance_id WHERE v.name LIKE '"+prefix+"%' OR vm.display_name='"+prefix+"-vm';"
rows=sql(c,q);out={'snapshots':[x for x in rows if'status'in x],'references':[x for x in rows if'role'in x],'volumes':[x for x in rows if'pool'in x]};assert len(out['snapshots'])==7 and len(out['volumes'])==6
(root/(c+'-db-before.json')).write_text(json.dumps(out,indent=2));print(c,'Independent DB inventory',len(out['snapshots']),len(out['references']),len(out['volumes']))
